WITH flattened AS (SELECT id, log_ts, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, value), unpacked AS (SELECT log_ts, status_code, key, value, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 8) != 0 AS INT) AS has_fault FROM flattened WHERE status_code BETWEEN 264 AND 291), cleaned AS (SELECT status_code, key, value, status_code_high, ROUND(status_code * 0.85, 2) AS adjusted_status_code FROM unpacked WHERE log_ts > TIMESTAMP '2025-06-01 15:00:00' AND has_fault BETWEEN 0 AND 1), scored AS (SELECT key, status_code_high, adjusted_status_code, CUME_DIST() OVER w_part AS status_code_cume_dist, PERCENT_RANK() OVER w_recent AS status_code_percent_rank, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) AS status_code_share FROM cleaned WINDOW w_part AS (PARTITION BY key ORDER BY status_code ASC), w_recent AS (ORDER BY status_code DESC)), scored_app_logs AS (SELECT key, status_code_high, status_code_cume_dist, status_code_percent_rank, PERCENT_RANK() OVER (PARTITION BY key ORDER BY adjusted_status_code ASC NULLS FIRST) AS adjusted_status_code_percent_rank, MIN(status_code_cume_dist) OVER (PARTITION BY key) AS key_min_status_code_cume_dist FROM scored), cleaned_app_logs AS (SELECT key, status_code_high, status_code_cume_dist, adjusted_status_code_percent_rank, CASE WHEN key IN ('region', 'trace') THEN 'Tier 1' ELSE 'Other' END AS key_group, COALESCE(key, 'N/A') AS resolved_key FROM scored_app_logs WHERE key IS DISTINCT FROM 'trace'), cleaned_app_logs_2 AS (SELECT *, status_code_cume_dist - adjusted_status_code_percent_rank AS status_code_cume_dist_minus_adjusted_status_code_percent_rank FROM cleaned_app_logs WHERE adjusted_status_code_percent_rank < 0.46), summary AS (SELECT CASE WHEN status_code_cume_dist >= 0.88 THEN 'LARGE' ELSE 'SMALL' END AS status_code_cume_dist_tier, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(DISTINCT key) AS distinct_keys, COUNT(CASE WHEN key = 'region' THEN 1 END) AS region_count, COUNT(DISTINCT key) AS distinct_keys_2, COUNT_IF(key = 'trace') AS trace_events, COUNT(DISTINCT key) AS distinct_keys_3 FROM cleaned_app_logs_2 GROUP BY CASE WHEN status_code_cume_dist >= 0.88 THEN 'LARGE' ELSE 'SMALL' END) SELECT status_code_cume_dist_tier, key_list, distinct_keys, distinct_keys_2, trace_events FROM summary ORDER BY distinct_keys ASC
